import Foundation

// Ported from index.html: formatDate(), reportName(), reportCategories(),
// REPORT_AWAY, reportBucket(), reportCounts(), reportCountsLine(),
// reportBreakdown(), reportDateRange(), reportDetailLine(), buildReport().
// Spec: tests/test_report_js.py. The text must match the web client's byte for
// byte; ReportTests.swift pins whole reports generated by the JS itself.

enum ReportFormat: String, Sendable, Equatable, Codable {
    case detailed
    case strength
}

struct ReportOptions: Sendable, Equatable, Codable {
    typealias Format = ReportFormat
    var format: ReportFormat = .detailed
    var splitLeavePass: Bool = false
}

/// One direct child of the viewed unit, with its whole subtree's unit ids.
struct ReportGroup: Sendable, Equatable {
    var name: String
    var ids: [Int]
}

struct ReportContext: Sendable, Equatable {
    var unitName: String
    /// `formatReportDate(_:timeZone:)` of now, in the organization's zone.
    var dateLabel: String
    /// The duty day, "YYYY-MM-DD".
    var today: String
    /// The viewed unit's direct children in tree order; empty for a leaf unit.
    var groups: [ReportGroup] = []
}

extension ReportContext {
    /// `reportContext()`: the groups are the unit's children (name order),
    /// each with its subtree.
    init(unitId: Int, unitName: String, dateLabel: String, today: String, tree: UnitTree) {
        self.init(unitName: unitName, dateLabel: dateLabel, today: today,
                  groups: tree.children(of: unitId).map { ReportGroup(name: $0.name, ids: tree.subtree(of: $0.id)) })
    }
}

/// `formatDate(d)`: "13 Nov 2026", the date as it reads in `timeZone` (the
/// organization's, never the phone's).
func formatReportDate(_ date: Date, timeZone: TimeZone) -> String {
    var cal = Calendar(identifier: .gregorian)
    cal.timeZone = timeZone
    let c = cal.dateComponents([.year, .month, .day], from: date)
    return "\(c.day ?? 0) \(Months.short[(c.month ?? 1) - 1]) \(c.year ?? 0)"
}

/// `String.prototype.padEnd`, which counts UTF-16 code units.
private func padEnd(_ s: String, _ width: Int) -> String {
    let n = s.utf16.count
    return n >= width ? s : s + String(repeating: " ", count: width - n)
}

/// One soldier's name column: the rank padded to 5, then "Last, First".
func reportName(_ p: Soldier) -> String {
    "\(padEnd(p.rank, 5)) \(lastFirst(p))"
}

/// (key, label) pairs; a key may join two buckets with "+".
func reportCategories(splitLeavePass: Bool) -> [(key: String, label: String)] {
    [("tdy", "TDY")]
        + (splitLeavePass ? [("leave", "Leave"), ("pass", "Pass")] : [("leave+pass", "Leave & Pass")])
        + [("late", "Late"), ("excused", "Excused"), ("other", "Other"), ("ftr", "FTR")]
}

enum ReportRules {
    /// `REPORT_AWAY`: any other status is counted (and listed) as Other.
    static let away: [String] = ["tdy", "leave", "pass", "late", "excused", "other", "ftr"]
}

/// "pdy", "unaccounted", "noform" (strength only: accounted for but never at
/// formation), or an away status from `ReportRules.away`.
func reportBucket(_ p: Soldier, today: String, strength: Bool = false) -> String {
    if p.status == "present" {
        if p.presentDate != today { return "unaccounted" }
        return strength && p.noFormation ? "noform" : "pdy"
    }
    return ReportRules.away.contains(p.status) ? p.status : "other"
}

struct ReportCounts: Sendable, Equatable {
    var assigned: Int
    /// Per bucket; every key of `reportBucket` is present, 0 when empty.
    var buckets: [String: Int]

    subscript(key: String) -> Int { buckets[key] ?? 0 }
}

func reportCounts(_ people: [Soldier], today: String, strength: Bool = false) -> ReportCounts {
    var c: [String: Int] = ["pdy": 0, "noform": 0, "unaccounted": 0]
    for k in ReportRules.away { c[k] = 0 }
    for p in people { c[reportBucket(p, today: today, strength: strength), default: 0] += 1 }
    return ReportCounts(assigned: people.count, buckets: c)
}

func reportCountsLine(_ c: ReportCounts, splitLeavePass: Bool) -> String {
    let n = { (key: String) in key.split(separator: "+").reduce(0) { $0 + c[String($1)] } }
    var parts = ["\(c.assigned) Assigned", "\(c["pdy"]) PDY"]
    if c["noform"] != 0 { parts.append("\(c["noform"]) Not in formation") }
    for (key, label) in reportCategories(splitLeavePass: splitLeavePass) where n(key) != 0 {
        parts.append("\(n(key)) \(label)")
    }
    if c["unaccounted"] != 0 { parts.append("\(c["unaccounted"]) Unaccounted") }
    return parts.joined(separator: ", ")
}

/// Per sub-unit lines plus a total; [] for a leaf unit. Anyone directly in
/// the viewed unit (or somewhere no group claims) is filed under HQ.
func reportBreakdown(_ people: [Soldier], ctx: ReportContext, splitLeavePass: Bool,
                     strength: Bool = false) -> [String] {
    if ctx.groups.isEmpty { return [] }
    // The JS claims by object identity; people are unique by position here.
    var claimed = Set<Int>()
    var lines: [String] = []
    for g in ctx.groups {
        let ids = Set(g.ids)
        var members: [Soldier] = []
        for (i, p) in people.enumerated() where ids.contains(p.unitId) {
            members.append(p)
            claimed.insert(i)
        }
        if !members.isEmpty {
            lines.append("\(g.name): \(reportCountsLine(reportCounts(members, today: ctx.today, strength: strength), splitLeavePass: splitLeavePass))")
        }
    }
    let hq = people.enumerated().filter { !claimed.contains($0.offset) }.map(\.element)
    if !hq.isEmpty {
        lines.append("HQ: \(reportCountsLine(reportCounts(hq, today: ctx.today, strength: strength), splitLeavePass: splitLeavePass))")
    }
    lines.append("TOTAL: \(reportCountsLine(reportCounts(people, today: ctx.today, strength: strength), splitLeavePass: splitLeavePass))")
    return lines
}

func reportDateRange(_ p: Soldier) -> String {
    if p.from.isEmpty && p.to.isEmpty { return "" }
    return "\(formatDateShort(p.from))-\(formatDateShort(p.to))"
}

func reportDetailLine(_ p: Soldier, bucket: String) -> String {
    var parts: [String] = []
    if bucket == "tdy" && !p.notes.isEmpty {
        if let r = p.notes.range(of: " - ") {               // school | location
            parts.append(String(p.notes[..<r.lowerBound]))
            parts.append(String(p.notes[r.upperBound...]))
        } else {
            parts.append(p.notes)
        }
    }
    let line = { reportName(p) + (parts.isEmpty ? "" : "  " + parts.joined(separator: " | ")) }
    // Late and excused are same-day: the reason, never a date range.
    if bucket == "late" || bucket == "excused" {
        let reason = jsTrim(p.notes)
        if !reason.isEmpty { parts.append(reason) }
        return line()
    }
    if bucket == "other" { parts.append(p.notes.isEmpty ? "Other" : "Other: \(p.notes)") }
    if bucket != "pdy" && bucket != "unaccounted" {
        let dr = reportDateRange(p)
        if !dr.isEmpty { parts.append(dr) }
    }
    return line()
}

/// The whole text of both report formats. `people` is the roster (the whole
/// subtree). Nobody is ever left out: anyone unaccounted is counted and listed.
func buildReport(_ people: [Soldier], _ opts: ReportOptions, _ ctx: ReportContext) -> String {
    let split = opts.splitLeavePass
    var lines = [ctx.unitName, ctx.dateLabel]
    if opts.format == .strength {
        let breakdown = reportBreakdown(people, ctx: ctx, splitLeavePass: split, strength: true)
        lines.append("")
        if !breakdown.isEmpty { lines.append(contentsOf: breakdown) }
        else { lines.append(reportCountsLine(reportCounts(people, today: ctx.today, strength: true), splitLeavePass: split)) }
        return lines.joined(separator: "\n")
    }

    lines.append("\(people.count) Assigned")
    let breakdown = reportBreakdown(people, ctx: ctx, splitLeavePass: split)
    if !breakdown.isEmpty { lines.append(contentsOf: ["", "BY UNIT"] + breakdown) }

    let inBucket = { (keys: [String]) in people.filter { keys.contains(reportBucket($0, today: ctx.today)) } }
    let present = inBucket(["pdy"]).stableSorted(byComparator: rankCompare)
    lines.append(contentsOf: ["", "PDY \(present.count)"])
    lines.append(contentsOf: present.map(reportName))

    let sections: [(heading: String, keys: [String], sorter: JSComparator<Soldier>)] =
        (split ? [("Leave", ["leave"], endDateCompare), ("Pass", ["pass"], endDateCompare)]
               : [("Leave & Pass", ["leave", "pass"], endDateCompare)])
        + [("TDY", ["tdy"], endDateCompare),
           ("LATE", ["late"], rankCompare),
           ("EXCUSED", ["excused"], rankCompare),
           ("OTHER", ["other"], endDateCompare),
           ("FTR", ["ftr"], endDateCompare),
           ("UNACCOUNTED", ["unaccounted"], rankCompare)]
    for (heading, keys, sorter) in sections {
        let list = inBucket(keys).stableSorted(byComparator: sorter)
        if list.isEmpty { continue }
        lines.append(contentsOf: ["", "\(heading) \(list.count)"])
        lines.append(contentsOf: list.map { reportDetailLine($0, bucket: reportBucket($0, today: ctx.today)) })
    }
    return lines.joined(separator: "\n")
}

/// `String.prototype.trim()`: whitespace and line terminators at both ends.
func jsTrim(_ s: String) -> String {
    s.trimmingCharacters(in: .whitespacesAndNewlines)
}
